$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$guardBlock = Decode ""

$routePath = Join-Path $root "app\api\market\requests\[id]\offers\route.ts"
$providerJobsPath = Join-Path $root "app\api\provider\jobs\route.ts"

foreach ($path in @($routePath, $providerJobsPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "12.94 : fichier requis introuvable : $path"
    }
}

$route = [System.IO.File]::ReadAllText($routePath)
$providerJobs = [System.IO.File]::ReadAllText($providerJobsPath)

if (-not $providerJobs.Contains("KLYX_PROVIDER_MULTI_JOBS_API_12_93")) {
    throw "12.94 : Provider Jobs 12.93 introuvable."
}

if (-not $route.Contains("KLYX_MULTI_SLOT_OFFER_SERVER_GUARD_12_94")) {
    $anchor = "    const { data: offer, error } = await supabaseAdmin"

    $anchorIndex = $route.IndexOf($anchor)

    if ($anchorIndex -lt 0) {
        throw "12.94 : ancre POST offre introuvable."
    }

    $patchIndex = $anchorIndex

    $route = $route.Insert($patchIndex, $guardBlock)
}

[System.IO.File]::WriteAllText($routePath, $route, $utf8)

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupPath = $routePath + ".snapshot-12-94-" + $timestamp
[System.IO.File]::WriteAllText($backupPath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.94 APPLIQUE"
Write-Host "======================================"
Write-Host "Offre multi cote serveur : PROTEGEE"
Write-Host "Prestataire 1/N : BLOQUE"
Write-Host "Prestataire N/N : AUTORISE"
Write-Host "Planning modifie : BLOQUE"
Write-Host "Prix multi <= 0 : BLOQUE"
Write-Host "Missions simples : CONSERVEES"
Write-Host "Accept guard 12.84 : CONSERVE"
Write-Host "Execution automatique : NON"
Write-Host "======================================"
Write-Host ""
